#!/usr/bin/env python3
"""Reader for the v2 pipeline repetitions: one tab per run, a metrics table, and every row with its gate result, answer, and the editor's verdict.
Usage: python3 cluster/pipeline_page.py <out.html> <run_dir> [run_dir ...]"""
import json, sys, html, os, collections
OUT = sys.argv[1]; RUNS = sys.argv[2:]; E = html.escape
def load(p): return [json.loads(l) for l in open(p)] if os.path.exists(p) else []
data = {}
for d in RUNS:
    name = os.path.basename(d.rstrip('/')); rows = load(f'{d}/rows.jsonl'); checks = {c['id']: c for c in load(f'{d}/checks.jsonl') if c.get('verdict')}; qs = {q['id']: q for q in load(f'{d}/questions_gated.jsonl')}
    m = json.load(open(f'{d}/metrics.json')) if os.path.exists(f'{d}/metrics.json') else {}
    unanswered = [q for i, q in qs.items() if i not in {r['id'] for r in rows}]
    data[name] = dict(metrics=m, rows=[dict(id=r['id'], topic=r.get('topic'), form=r.get('form'), user_type=r.get('user_type'), gate=r.get('gate') or {}, messages=r['messages'], facts_used=r.get('facts_used') or [], beyond=r.get('beyond_sheet') or [], check=checks.get(r['id'])) for r in sorted(rows, key=lambda r: (r.get('topic') or '', r['id']))],
                      unanswered=[dict(id=q['id'], user_el=q['user_el'], gate=q.get('gate') or {}) for q in unanswered])
KEYS = ['questions', 'gate_keep_rate', 'rows', 'multi_turn', 'names_greece_rate', 'mannerism_rate', 'ai_boilerplate', 'exclamations_per_row', 'beyond_sheet_rows', 'answer_chars_median', 'checked', 'edit_rate', 'greekness', 'fact_doubts']
css = """
:root{--ground:#eef0f2;--paper:#fff;--ink:#1b1f27;--muted:#626a78;--rule:#d2d7df;--accent:#2f6f8f;--user:#f2f5f8;--ok:#2b7a58;--ok-bg:#e6f3ec;--ed:#a86c14;--ed-bg:#f9efdc;--rw:#b13b3b;--rw-bg:#f8e6e6;--gate:#3b4f8a;--gate-bg:#e9edf7;--ph:#7a3f9a;--ph-bg:#f1e6f8;
--display:"Fraunces",Georgia,serif;--sans:"IBM Plex Sans",-apple-system,"Segoe UI",Helvetica,Arial,sans-serif;--mono:"IBM Plex Mono",ui-monospace,Menlo,monospace}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){--ground:#15181e;--paper:#1e2229;--ink:#e6e8ec;--muted:#9aa3b2;--rule:#333a46;--accent:#8fc1e0;--user:#252a33;--ok:#7fcaa4;--ok-bg:#1f3a2e;--ed:#e3b46a;--ed-bg:#3d3120;--rw:#ee8f8f;--rw-bg:#40272a;--gate:#9fb0e6;--gate-bg:#252c40;--ph:#c9a6e6;--ph-bg:#33253d}}
:root[data-theme="dark"]{--ground:#15181e;--paper:#1e2229;--ink:#e6e8ec;--muted:#9aa3b2;--rule:#333a46;--accent:#8fc1e0;--user:#252a33;--ok:#7fcaa4;--ok-bg:#1f3a2e;--ed:#e3b46a;--ed-bg:#3d3120;--rw:#ee8f8f;--rw-bg:#40272a;--gate:#9fb0e6;--gate-bg:#252c40;--ph:#c9a6e6;--ph-bg:#33253d}
*{box-sizing:border-box}body{margin:0;background:var(--ground);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.5}
header{padding:28px 24px 0;max-width:1100px;margin:0 auto}h1{font-family:var(--display);font-weight:500;font-size:34px;margin:0 0 6px;letter-spacing:-.01em;text-wrap:balance}.lede{color:var(--muted);max-width:74ch;margin:0 0 14px}
.pills{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:14px}.pill{border:1px solid var(--rule);background:var(--paper);color:var(--ink);border-radius:999px;padding:6px 14px;font:inherit;font-size:14px;cursor:pointer}.pill[aria-pressed="true"]{background:var(--accent);border-color:var(--accent);color:#fff}
main{max-width:1100px;margin:0 auto;padding:0 24px 60px}table{border-collapse:collapse;font-size:13px;margin:0 0 18px;background:var(--paper);border:1px solid var(--rule);border-radius:10px;overflow:hidden}th,td{padding:6px 10px;border-bottom:1px solid var(--rule);text-align:right;font-variant-numeric:tabular-nums}th:first-child,td:first-child{text-align:left;font-family:var(--mono);font-size:12px}
.wrap{overflow-x:auto}article{background:var(--paper);border:1px solid var(--rule);border-radius:10px;margin-bottom:16px;overflow:hidden}
.gate{padding:8px 18px;border-left:5px solid var(--gate);background:var(--gate-bg);font-size:13px}.turn{padding:12px 18px;white-space:pre-wrap;overflow-wrap:anywhere;max-width:84ch}.turn.user{background:var(--user);color:var(--muted);font-size:14px;max-width:none}.role{font-family:var(--mono);font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-bottom:4px}
.meta{font-family:var(--mono);font-size:11.5px;color:var(--muted);padding:8px 18px;border-top:1px solid var(--rule);display:flex;flex-wrap:wrap;gap:4px 14px}.check{padding:10px 18px;border-left:5px solid var(--vc);background:var(--vbg);font-size:13.5px;display:grid;gap:3px}.check .v{font-weight:600}.ph{background:var(--ph-bg);color:var(--ph);border-radius:4px;padding:0 4px;font-family:var(--mono);font-size:12px}
"""
out = ['<title>Personality Pipeline Runs</title>', '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500&family=IBM+Plex+Sans:wght@400;600&family=IBM+Plex+Mono&display=swap">', f'<style>{css}</style>',
       '<header><h1>Personality Pipeline Runs</h1><p class="lede">The version-2 pipeline on the batches the owner flagged, repeated with different seeds: questions written without the fact in view, a self-containment gate by a second model, answers written with the whole sheet, and a Γ correction by an editor that did not write the rows. Each tab is one repetition; the table compares them. Every card shows the gate\'s reading of the question, the answer (with the editor\'s version where it changed), the facts used and anything the writer declared beyond the sheet.</p>',
       '<div class="pills" role="group">' + ''.join(f'<button class="pill" data-r="{E(n)}" aria-pressed="{"true" if k == 0 else "false"}">{E(n)} · {len(d["rows"])} rows</button>' for k, (n, d) in enumerate(data.items())) + '</div></header>',
       '<main><div class="wrap"><table><tr><th>metric</th>' + ''.join(f'<th>{E(n)}</th>' for n in data) + '</tr>' + ''.join('<tr><td>' + k + '</td>' + ''.join(f'<td>{E(str(d["metrics"].get(k, "—")))}</td>' for d in data.values()) + '</tr>' for k in KEYS) + '</table></div><div id="cards"></div></main>',
       '<script>const DATA=' + json.dumps(data, ensure_ascii=False).replace('</', '<\\/') + ';',
       r"""const E=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));const M=s=>E(s).replace(/\[ΟΝΟΜΑ\]|\[ΗΜΕΡΟΜΗΝΙΑ ΓΝΩΣΗΣ\]|\[ΑΔΕΙΑ\]/g,m=>`<span class="ph">${m}</span>`);let cur=Object.keys(DATA)[0];
function render(){document.querySelectorAll('.pill').forEach(b=>b.setAttribute('aria-pressed',b.dataset.r===cur));const d=DATA[cur];
document.getElementById('cards').innerHTML=d.rows.map(r=>{const g=r.gate||{};const k=r.check;const vc=k?({ok:'ok',edited:'ed',rewrite:'rw'}[k.verdict]||'ed'):null;
return `<article><div class="gate">gate: <b>${E(g.action||'—')}</b>${g.self_contained===false?' · not self-contained':''}${g.scope_el?` · needs: ${E(g.scope_el)}`:''}${g.narrowed_el?` · narrowed to: ${E(g.narrowed_el)}`:''}</div>${r.messages.map(m=>`<div class="turn ${m.role}"><div class="role">${E(m.role)}</div>${M(m.content)}</div>`).join('')}${k?`<div class="check" style="--vc:var(--${vc});--vbg:var(--${vc}-bg)"><div class="v">editor: ${E(k.verdict)} · Greekness ${E(k.greekness)}</div>${(k.changes||[]).map(x=>`<div>• ${E(x)}</div>`).join('')}${k.fact_doubt?`<div><b>fact doubt:</b> ${E(k.fact_doubt)}</div>`:''}${k.verdict!=='ok'?`<div><b>editor's version:</b> ${M(k.edited_last_answer||'')}</div>`:''}</div>`:''}<div class="meta"><span>${E(r.id)}</span><span>${E(r.topic)} · ${E(r.form)}</span><span>${E(r.user_type||'')}</span><span>facts: ${E((r.facts_used||[]).join(', '))}</span>${r.beyond.length?`<span>beyond sheet: ${E(r.beyond.join(' | '))}</span>`:''}</div></article>`}).join('')+(d.unanswered.length?`<p class="lede">Questions without an answer row: ${d.unanswered.map(q=>E(q.id)+' ('+E(q.gate.action||'')+')').join(', ')}</p>`:'');window.scrollTo({top:0});}
document.querySelectorAll('.pill').forEach(b=>b.addEventListener('click',()=>{cur=b.dataset.r;render();}));render();</script>"""]
open(OUT, 'w').write('\n'.join(out)); print('wrote', OUT, os.path.getsize(OUT) // 1024, 'KB')
